"use client";

import { Suspense, useMemo, type ReactNode } from "react";
import { NuqsAdapter } from "nuqs/adapters/next/app";
import {
  DataGridProvider,
  DataGridRoot,
  DataGridHeader,
  DataGridBody,
  defineColumns,
} from "@/registry/default/components/data-grid/data-grid";
import {
  DataGridToolbar,
  DataGridSearch,
  DataGridFilterMenu,
  DataGridColumnsMenu,
} from "@/registry/default/components/data-grid-toolbar/data-grid-toolbar";
import { DataGridHeaderDropdown } from "@/registry/default/components/data-grid-context-menu/data-grid-context-menu";
import { DataGridUrlState, useDataGridUrlPagination } from "@/registry/default/components/data-grid-url-state/data-grid-url-state";
import { DataGridPaginationBar } from "@/registry/default/components/data-grid-pagination/data-grid-pagination";
import { generateDemoRows, type DemoRow } from "./demo-data";

const columns = defineColumns<DemoRow>()([
  { id: "name", header: "Name", accessorKey: "name", type: "text", width: 160 },
  { id: "email", header: "Email", accessorKey: "email", type: "text", width: 200 },
  {
    id: "role",
    header: "Role",
    accessorKey: "role",
    type: "select",
    options: {
      choices: [
        "Admin",
        "User",
        "Editor",
        "Viewer",
        "Manager",
      ],
    },
    width: 130,
    filterable: true,
  },
  { id: "score", header: "Logins (30 days)", accessorKey: "score", type: "number", width: 90 },
] as const);

/** The pagination hook reads `useSearchParams()` through nuqs; Next.js requires Suspense around it during static prerendering. */
function DataGridUrlStateDemoInner(): ReactNode {
  const rows = useMemo(() => generateDemoRows(60), []);
  const url = useDataGridUrlPagination({ prefix: "demo" });

  return (
    <div className="w-full flex flex-col gap-3">
      <p className="text-sm text-muted-foreground">
        Sort, filter, search, change page, resize a column, or pin one from its header menu, then reload this
        page: the URL carries that state and the grid comes back exactly as you left it.
      </p>
      <div className="flex h-[420px] flex-col overflow-hidden rounded-md border border-border">
        {/* headerClickBehavior="sort" so the URL-synced sortState is actually reachable in this demo */}
        <DataGridProvider defaultData={rows} columns={columns} headerClickBehavior="sort" {...url}>
          <DataGridUrlState prefix="demo" spec={["sort", "filter", "search"]} layout={["order", "hidden", "widths", "pins"]} />
          <DataGridToolbar>
            <DataGridSearch />
            <DataGridFilterMenu />
            <DataGridColumnsMenu />
          </DataGridToolbar>
          <DataGridRoot
            className="min-h-0 flex-1 rounded-none border-none"
            renderHeaderMenu={(ctx) => <DataGridHeaderDropdown {...ctx} />}
          >
            <DataGridHeader />
            <DataGridBody />
          </DataGridRoot>
          <DataGridPaginationBar />
        </DataGridProvider>
      </div>
    </div>
  );
}

/**
 * Sort/filter/search state synced to the URL via nuqs, and `page`/`pageSize` synced the same way
 * via `useDataGridUrlPagination` — reload the page or share the link and the grid's view comes
 * back exactly, including which page it was on. `NuqsAdapter` is app-router here
 * (`nuqs/adapters/next/app`); swap for your framework's adapter (pages router, Remix, React
 * Router, plain React) per the nuqs docs. In an app that already renders `NuqsAdapter` once near
 * the root, drop this inner wrapper — adapters must not be nested.
 */
export default function DataGridUrlStateDemo(): ReactNode {
  return (
    <NuqsAdapter>
      <Suspense fallback={null}>
        <DataGridUrlStateDemoInner />
      </Suspense>
    </NuqsAdapter>
  );
}

/** Deterministic LCG so SSR/CSR markup match without Math.random(); shared across example rows. */
function createSeededLcg(seed: number) {
  let state = seed;
  return () => {
    state = (state * 1103515245 + 12345) & 0x7fffffff;
    return state / 0x7fffffff;
  };
}

export type DemoRow = {
  id: string;
  name: string;
  email: string;
  age: number;
  active: boolean;
  role: string;
  joined: string;
  score: number;
};

const ROLES = ["Admin", "User", "Editor", "Viewer", "Manager"] as const;
const FIRST_NAMES = [
  "Ava", "Liam", "Mia", "Noah", "Priya", "Mateo", "Yuki", "Omar", "Elena", "Kofi",
  "Sofia", "Ravi", "Hannah", "Diego", "Amara", "Lukas", "Nadia", "Tomas", "Ingrid", "Jamal",
  "Chloe", "Arjun", "Fatima", "Ethan", "Leila", "Marco", "Zara", "Felix", "Mei", "Jonas",
  "Aisha", "Pavel", "Clara", "Hugo", "Nina", "Samir", "Alma", "Oskar", "Lucia", "Dev",
] as const;
const LAST_NAMES = [
  "Becker", "Okafor", "Nguyen", "Lindqvist", "Alvarez", "Tanaka", "Haddad", "Moreau", "Kowalski", "Joshi",
  "Rossi", "Teixeira", "Novak", "Fischer", "Mensah", "Larsen", "Castillo", "Ivanov", "Yamamoto", "Duarte",
  "Brennan", "Hoffmann", "Santos", "Kaya", "Weber", "Adeyemi", "Petrov", "Lopez", "Chen", "Murphy",
  "Bianchi", "Hartmann", "Ito", "Reyes", "Sorensen", "Qureshi", "Ferraz", "Dubois", "Park", "Svensson",
] as const;

/**
 * Generates `count` deterministic rows of a fictional user directory (seed 42, stable across renders).
 * `score` is the number of logins in the last 30 days.
 */
export function generateDemoRows(count: number, seed = 42): DemoRow[] {
  const next = createSeededLcg(seed);
  const rows: DemoRow[] = [];
  const emailUses = new Map<string, number>();
  for (let i = 0; i < count; i++) {
    const first = FIRST_NAMES[Math.floor(next() * FIRST_NAMES.length)]!; // fixed non-empty literal arrays
    const last = LAST_NAMES[Math.floor(next() * LAST_NAMES.length)]!;
    const handle = `${first}.${last}`.toLowerCase();
    const uses = (emailUses.get(handle) ?? 0) + 1;
    emailUses.set(handle, uses);
    rows.push({
      id: `row-${i}`,
      name: `${first} ${last}`,
      email: `${handle}${uses > 1 ? uses : ""}@example.com`,
      age: Math.floor(next() * 44) + 21,
      active: next() > 0.5,
      role: ROLES[Math.floor(next() * ROLES.length)]!, // ROLES is a fixed non-empty literal array
      joined: `${2020 + Math.floor(next() * 5)}-${String(Math.floor(next() * 12) + 1).padStart(2, "0")}-${String(Math.floor(next() * 28) + 1).padStart(2, "0")}`,
      score: Math.floor(next() * 100),
    });
  }
  return rows;
}
